/**
 * "Free" and "Creator" server tags — ONE pure rule set used by every surface
 * (customer list/detail/games/overview, admin fleet/detail/client/partner views).
 * No DB import: lib/server-ownership-tags-data.ts does the (batched) lookups and
 * feeds this function. Rules are derived from the real data model:
 *
 *  - Server.isFree = "no billing, ever" (admin-granted free servers, adminGrantFreeVps).
 *  - A PartnerGrant (lib/partner-grants.ts) links to its server via serverId. The grant
 *    server is sold at $0 but isFree is deliberately NOT set, so isFree alone would
 *    call a creator's server "paid".
 *
 * A grant is LIVE while its status is ACTIVE or EXPIRING AND the grant has not lapsed
 * or been paid past (grantPhase, the same rule the hourly partnerGrantSweep applies —
 * evaluated here too so the tag is right before the sweep next runs).
 *   live grant                          -> Free + Creator
 *   REVOKED / EXPIRED / CONVERTED / FAILED, or phase "converted"/"expired"
 *                                       -> neither tag from the grant (the server is no
 *                                          longer an unpaid creator gift: revoked = we
 *                                          withdrew it, converted = somebody paid)
 *   isFree server (no live grant)       -> Free (+ Creator only when its owner is a
 *                                          ReferralPartner: granted, not purchased)
 *   everything else                     -> no tags; a paid server never shows Free.
 */
import { grantPhase } from "./partner-grant-rules";

export type OwnershipTagKey = "free" | "creator";
export type OwnershipTag = { key: OwnershipTagKey; label: string; title: string };

export type GrantFacts = {
  status: string;
  expiresAt: Date | null;
  noticeSentAt: Date | null;
  finalNoticeSentAt: Date | null;
};

export type OwnershipInput = {
  isFree: boolean;
  /** Live Server.expiresAt (needed to detect a paid-renewed grant before the sweep flips it). */
  serverExpiresAt: Date | null;
  /** The PartnerGrant row for this server, if any (PartnerGrant.serverId is unique). */
  grant: GrantFacts | null;
  /** The server's owner has a ReferralPartner record (creator/partner program). */
  ownerIsPartner: boolean;
};

export function isGrantLive(grant: GrantFacts | null, serverExpiresAt: Date | null, now: Date): boolean {
  if (!grant) return false;
  if (grant.status !== "ACTIVE" && grant.status !== "EXPIRING") return false;
  const phase = grantPhase(grant, serverExpiresAt, now);
  return phase !== "converted" && phase !== "expired";
}

export function serverOwnershipTags(input: OwnershipInput, now: Date = new Date()): OwnershipTag[] {
  const live = isGrantLive(input.grant, input.serverExpiresAt, now);
  const free = live || input.isFree;
  const creator = live || (input.isFree && input.ownerIsPartner);
  const out: OwnershipTag[] = [];
  if (free) {
    out.push({
      key: "free",
      label: "Free",
      title: live ? "Free for the length of the creator grant — nothing is charged" : "Free — this server is never billed",
    });
  }
  if (creator) {
    out.push({ key: "creator", label: "Creator", title: "Belongs to a Nxeon creator partner and was granted, not purchased" });
  }
  return out;
}

/** True when the server is genuinely not billed right now (isFree or a live grant). */
export function isEffectivelyFree(input: OwnershipInput, now: Date = new Date()): boolean {
  return input.isFree || isGrantLive(input.grant, input.serverExpiresAt, now);
}
