/* ------------------------------------------------------------------ *
 * MRR
 * ------------------------------------------------------------------ */

/**
 * The shape of a server row needed to price its monthly contribution —
 * exactly `PricedServer` (lib/renewal-charge.ts) plus the fields this file's
 * own free/suspended/deleting short-circuits need.
 */
export type MrrServer = PricedServer & {
  status: string;
  isFree: boolean;
};

/**
 * Fetches the four admin-priced renewal inputs together, ONCE, for callers
 * that need to price a whole fleet (serverMonthlyCents/fleetMrrCents below).
 * Deliberately NOT exported from lib/renewal-charge.ts itself — that file is
 * imported by a CLIENT component (the deploy wizard's term cards) and stays
 * free of anything that touches the database; every one of these four is a
 * `getSettingInt` read and must stay server-only.
 */
export async function currentRenewalPrices(): Promise<RenewalPrices> {
  const [ipMonthlyCents, extraDiskPerGbCentsVal, backupPlusCents, annualPct] = await Promise.all([
    dedicatedIpMonthlyCents(),
    extraDiskPerGbCents(),
    backupPlusMonthlyCents(),
    annualDiscountPct(),
  ]);
  return { ipMonthlyCents, extraDiskPerGbCents: extraDiskPerGbCentsVal, backupPlusCents, annualDiscountPct: annualPct };
}

/**
 * What one server actually contributes per month.
 *
 * REAL DEFECT (2026-07-27 admin audit, extended 2026-09-10). "MRR" on /admin,
 * /admin/subscriptions and /admin/analytics was `SUM(plan.priceCents)` over
 * every non-free, non-DELETING server. Four things were wrong with that, all
 * in the flattering direction:
 *
 *   1. GAME SERVERS. A game server carries BOTH a base `planId` and a
 *      `gamePlanId` and is sold at the game plan's flat price — the exact reason
 *      `renewNow` reads `gamePlan.priceCents` (lib/actions.ts) after billing a
 *      $4.99 tier at the $8.99 base rate. The dashboard still made that mistake.
 *   2. TERM PRICE. `plan.priceCents` is the monthly LIST price. A server bought
 *      on a discounted 36-month term is billed far less per month than list, so
 *      list-price MRR overstates committed revenue for every long-term customer.
 *      /admin/products already normalises its add-on MRR with a
 *      price-over-term division; VPS MRR did not.
 *   3. SUSPENDED SERVERS. The renewal sweep SKIPS suspended servers — an
 *      admin-suspended or abuse-suspended machine is never charged (see
 *      `adminSuspendServer`) — yet it counted at full price forever.
 *   4. ADD-ONS. Found live 2026-09-10 on a real customer: their invoice was
 *      $19.98 (plan $16.99 + a $2.99/mo dedicated-IP surcharge, correctly
 *      billed every renewal per worker/billing.ts's own sweep), but "Monthly
 *      spend" on their admin page showed $16.99 — this function never priced
 *      dedicated IP, extra disk, or the Plus backup tier at all, the exact
 *      "second formula" lib/renewal-charge.ts's own docstring warns never to
 *      write ("there is ONE renewal formula... two incidents in one day came
 *      from a second copy"). Now delegates to `renewalCharge` — the same
 *      formula worker/billing.ts's sweep actually charges from — instead of
 *      maintaining an independent, incomplete copy.
 *
 * Returns 0 for anything not currently billable.
 */
export function serverMonthlyCents(s: MrrServer, prices: RenewalPrices): number {
  if (s.isFree) return 0;
  // Not billed while suspended or being torn down.
  if (s.status === "SUSPENDED" || s.status === "DELETING") return 0;
  const charge = renewalCharge(s, prices);
  return monthlyCents(charge.netCents, charge.months);
}

/**
 * A term price expressed per month. Mirrors `monthlyCents` in
 * components/admin/ProductTables.tsx, which has always normalised the add-on
 * catalogue this way; VPS pricing simply never used it.
 */
export function monthlyCents(priceCents: number, termMonths: number): number {
  const months = Math.max(1, termMonths || 1);
  return Math.round(priceCents / months);
}

/** Sum `serverMonthlyCents` across a fleet. */
export function fleetMrrCents(servers: MrrServer[], prices: RenewalPrices): number {
  return servers.reduce((n, s) => n + serverMonthlyCents(s, prices), 0);
}

/* ------------------------------------------------------------------ *
 * Audit attribution
 * ------------------------------------------------------------------ */
import { renewalCharge, type PricedServer, type RenewalPrices } from "./renewal-charge";
import { monthlyCents } from "./admin-metrics";
import type { DunningConfig } from "./dunning-config";

/**
 * What the admin server fleet list (`/admin/servers`) and server detail page
 * need beyond MRR: the REAL per-row renewal price (including add-ons and any
 * grandfathered override), and small scannable lifecycle tags. Pulled out as
 * pure functions — no DB access — so both the page and a test can call them
 * directly against plain objects.
 */

/**
 * A row's real renewal price, monthly-equivalent, INCLUDING add-ons and any
 * `grandfatheredRenewalCents` override — priced through `renewalCharge`, the
 * one shared formula, not a second copy of it.
 *
 * Deliberately does NOT zero out for SUSPENDED/DELETING the way
 * `serverMonthlyCents` (current MRR contribution) does — that zero is correct
 * for "how much revenue is this server generating right now" but wrong for a
