export const LIVE_STATUSES = ["RUNNING", "STOPPED", "SUSPENDED", "REINSTALLING"] as const;
/** Same, plus DELETING (still counts as "was deployed" for funnels). */
export const DEPLOYED_STATUSES = [...LIVE_STATUSES, "DELETING"] as const;

/** Accounts that count toward business numbers: not staff, not flagged internal/test. */
export const CUSTOMER_WHERE: Prisma.UserWhereInput = { ...REVENUE_USER_WHERE, role: "CUSTOMER" };

/** The exact select `serverMonthlyCents` (lib/admin-metrics.ts) needs. */
export const MRR_SERVER_SELECT = {
  isFree: true,
  status: true,
  termMonths: true,
  extraDiskGB: true,
  backupTier: true,
  annualDiscountPct: true,
  plan: { select: { name: true, priceCents: true } },
  gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
  dedicatedIp: { select: { id: true } },
  wantsDedicatedIp: true,
  grandfatheredRenewalCents: true,
} as const;

/** One paid-server lifetime: when it started, when it ended (null = still live). */
export type PaidLife = { userId: string; start: Date; end: Date | null };

/**
 * Every paid server lifetime we can reconstruct: live non-free servers (end
 * null) + archived (deleted) servers that ever took money. ServerArchive has
 * no isFree column, so "ever paid" = totalSpentCents > 0 — a free server that
 * was deleted never enters the model. Internal/test accounts excluded.
 */
export async function paidLifetimes(): Promise<PaidLife[]> {
  const [live, archived, excluded] = await Promise.all([
    db.server.findMany({
      where: { isFree: false, status: { in: [...LIVE_STATUSES] }, user: CUSTOMER_WHERE },
      select: { userId: true, createdAt: true },
    }),
    db.serverArchive.findMany({
      where: { totalSpentCents: { gt: 0 }, userId: { not: null } },
      select: { userId: true, provisionedAt: true, deletedAt: true },
  });
  return { cents: -(a._sum.amountCents ?? 0), count: a._count._all };
}

/** Current MRR, paying customers, billable servers. */
export async function mrrNow(): Promise<{ mrrCents: number; payingCustomers: number; billableServers: number; byUser: Map<string, number> }> {
  const [servers, prices] = await Promise.all([
    db.server.findMany({
      where: { status: { in: [...LIVE_STATUSES] }, isFree: false, user: CUSTOMER_WHERE },
      select: { ...MRR_SERVER_SELECT, userId: true },
    }),
    currentRenewalPrices(),
  ]);
  const byUser = new Map<string, number>();
  let mrr = 0;
  let billable = 0;
  for (const s of servers) {
    const c = serverMonthlyCents(s, prices);
    if (c <= 0) continue;
    mrr += c;
    billable++;
    byUser.set(s.userId, (byUser.get(s.userId) ?? 0) + c);
  }
  return { mrrCents: mrr, payingCustomers: byUser.size, billableServers: billable, byUser };
}

