export async function productInsights(r: InsightsRange): Promise<{ rows: ProductRow[]; nodesMissingCost: string[]; totalCostCents: number; totalMrrCents: number }> {
  const [servers, nodes, prices, newCur, newPrev] = await Promise.all([
    db.server.findMany({
      where: { status: { in: [...LIVE_STATUSES] }, user: CUSTOMER_WHERE },
      select: {
        ...MRR_SERVER_SELECT,
        nodeId: true,
        plan: { select: { name: true, priceCents: true, ramMB: true, slug: true } },
        gamePlan: { select: { name: true, priceCents: true, termMonths: true, ramMB: true, gameFamily: true } },
      },
    }),
    db.node.findMany({ select: { id: true, name: true, isPrimary: true, monthlyCostCents: true, enabled: true } }),
    currentRenewalPrices(),
    db.server.findMany({
      where: { createdAt: { gte: r.from, lt: r.to }, user: CUSTOMER_WHERE },
      select: { isFree: true, plan: { select: { slug: true, name: true } }, gamePlan: { select: { gameFamily: true } } },
    }),
    db.server.findMany({
      where: { createdAt: { gte: r.prevFrom, lt: r.prevTo }, user: CUSTOMER_WHERE },
      select: { isFree: true, plan: { select: { slug: true, name: true } }, gamePlan: { select: { gameFamily: true } } },
    }),
  ]);
  const primary = nodes.find((n) => n.isPrimary) ?? nodes[0];
  const nodeOf = (id: string | null) => id ?? primary?.id ?? "unknown";

  // RAM committed per node (all live servers incl. free — they occupy real RAM).
  const nodeRam = new Map<string, number>();
  for (const s of servers) nodeRam.set(nodeOf(s.nodeId), (nodeRam.get(nodeOf(s.nodeId)) ?? 0) + ramOf(s));
  const costPerMb = new Map<string, number | null>();
  for (const n of nodes) {
    const ram = nodeRam.get(n.id) ?? 0;
    costPerMb.set(n.id, n.monthlyCostCents != null && ram > 0 ? n.monthlyCostCents / ram : n.monthlyCostCents != null ? 0 : null);
  }

  const keyOf = (s: { gamePlan: { gameFamily: string } | null; plan: { slug: string; name: string } }) =>
    s.gamePlan ? { key: `game:${s.gamePlan.gameFamily}`, label: s.gamePlan.gameFamily, kind: "game" as const } : { key: `vps:${s.plan.slug}`, label: s.plan.name, kind: "vps" as const };

  const rows = new Map<string, ProductRow>();
  const ensure = (k: { key: string; label: string; kind: "game" | "vps" }) => {
    let row = rows.get(k.key);
    if (!row) {
      row = { ...k, active: 0, paid: 0, free: 0, newInRange: 0, newPrev: 0, mrrCents: 0, ramMB: 0, costCents: 0, costComplete: true, marginCents: 0, marginPct: null };
      rows.set(k.key, row);
    }
    return row;
  };
  for (const s of servers) {
    const row = ensure(keyOf(s));
    row.active++;
    if (s.isFree) row.free++;
    else row.paid++;
    row.mrrCents += serverMonthlyCents(s, prices);
    const ram = ramOf(s);
    row.ramMB += ram;
    const cpm = costPerMb.get(nodeOf(s.nodeId));
    if (cpm == null) row.costComplete = false;
    else row.costCents += cpm * ram;
  }
  for (const s of newCur) if (!s.isFree) ensure(keyOf(s)).newInRange++;
  for (const s of newPrev) if (!s.isFree) ensure(keyOf(s)).newPrev++;
  let totalCost = 0;
  let totalMrr = 0;
  for (const row of rows.values()) {
    row.costCents = Math.round(row.costCents);
    row.marginCents = row.mrrCents - row.costCents;
    row.marginPct = row.mrrCents > 0 && row.costComplete ? row.marginCents / row.mrrCents : null;
    totalCost += row.costCents;
    totalMrr += row.mrrCents;
  }
  return {
    rows: [...rows.values()].sort((a, b) => b.mrrCents - a.mrrCents || b.active - a.active),
    nodesMissingCost: nodes.filter((n) => n.enabled && n.monthlyCostCents == null).map((n) => n.name),
    totalCostCents: totalCost,
    totalMrrCents: totalMrr,
  };
}

