/**
 * Every paid server lifetime we can reconstruct: live non-free servers (end
 * null) + archived (deleted) servers that ever took money. ServerArchive has
 * no isFree column, so "ever paid" = totalSpentCents > 0 — a free server that
 * was deleted never enters the model. Internal/test accounts excluded.
 */
export async function paidLifetimes(): Promise<PaidLife[]> {
  const [live, archived, excluded] = await Promise.all([
