/**
 * Creator-account name styling — PURE rules (no DB), shared by components/ui/UserName.tsx.
 *
 * A "creator account" is a user with a ReferralPartner row linked to them
 * (ReferralPartner.userId; an invited creator who has claimed gets one too).
 * The loader is lib/creator-accounts-data.ts (one batched query per page).
 *
 * Colour never carries the meaning alone: the name text stays, and list rows add
 * the "Creator" chip. Precedence (so other states keep their meaning):
 *   suspended (red, separate badge)  -> never overridden: the row keeps its badge
 *   creator                          -> magenta (beats the green "paying" colour,
 *                                       which was the reason a creator rendered green)
 *   paying                           -> green
 *   else                             -> inherit
 */
export type NameToneInput = { creator: boolean; paying?: boolean };
export type NameTone = "creator" | "paying" | "default";

export function nameTone({ creator, paying }: NameToneInput): NameTone {
  if (creator) return "creator";
  if (paying) return "paying";
  return "default";
}

/** Tailwind/utility classes for a tone. "creator" uses the .nx-creator-name rule (brand-c token). */
export function nameToneClass(tone: NameTone): string {
  if (tone === "creator") return "nx-creator-name";
  if (tone === "paying") return "text-emerald-300";
  return "";
}

