import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";
import {
  isRevenueDescription,
  NON_REVENUE_PREFIXES,
  REVENUE_WHERE,
  ADMIN_CREDIT_WHERE,
  serverMonthlyCents,
  fleetMrrCents,
  monthlyCents,
  type MrrServer,
} from "../lib/admin-metrics.ts";
import type { RenewalPrices } from "../lib/renewal-charge.ts";

/** No add-ons, no annual discount — isolates the base plan/term arithmetic these
 *  tests exist to check, exactly as `serverMonthlyCents` behaved before it also
 *  started pricing add-ons. */
const NO_ADDONS: RenewalPrices = { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: 0 };

/**
 * The figures the admin console puts in front of an operator must be computed
 * from what they claim to measure. `lib/admin-metrics.ts` is the single source of
 * truth for that arithmetic; every one of its helpers exists because a headline
 * number was previously wrong in the flattering direction (a refund read as
 * revenue, a game server priced at the base VPS rate, a suspended machine billed
 * forever).
 *
 * The helper module was written and wired into the overview, but three financial
 * pages — /admin/billing, /admin/subscriptions, /admin/analytics — kept the exact
 * naive math the module's own docstrings name as the defect. These tests do two
 * jobs: prove the pure arithmetic, and PIN every financial surface to the helper
 * so a page cannot quietly drift back to `SUM(amountCents < 0)` for revenue or
 * `SUM(plan.priceCents)` for MRR.
 *
 * Source is stripped of comments/strings before any structural assertion — this
 * repo documents its incidents in the code, and a naive grep matches the incident
 * note and passes on broken code. See test/_source-tools.ts.
 */

const ROOT = join(import.meta.dirname, "..");

function code(rel: string): string {
  return stripCommentsAndStrings(readFileSync(join(ROOT, rel), "utf8"));
}

/* ================================================================== *
 * 1. Revenue classification — the pure rule
 * ================================================================== */

test("every reversal prefix classifies as NON-revenue", () => {
  for (const prefix of NON_REVENUE_PREFIXES) {
    assert.equal(
      isRevenueDescription(`${prefix} — whatever follows`),
      false,
      `a ledger row starting "${prefix}" is money leaving the business, not revenue`,
    );
  }
      `${page} shows revenue but does not use REVENUE_WHERE — a bare amountCents<0 sum ` +
        `counts refunds and affiliate cash-outs as revenue`,
    );
  }
});

test("every page that shows MRR derives it from serverMonthlyCents / fleetMrrCents", () => {
  // These three surface an MRR figure; each must price it through the helper so
  // game plans, term proration and suspended machines are handled — never a raw
  // sum of plan.priceCents.
  for (const page of ["app/admin/page.tsx", "app/admin/subscriptions/page.tsx", "app/admin/analytics/page.tsx"]) {
    const src = code(page);
    assert.ok(
      src.includes("fleetMrrCents") || src.includes("serverMonthlyCents"),
      `${page} shows MRR but does not use the pricing helper`,
    );
  }
});

test("billing 'Credits issued' uses ADMIN_CREDIT_WHERE (both credit tools)", () => {
  const src = code("app/admin/billing/page.tsx");
  assert.ok(
    src.includes("ADMIN_CREDIT_WHERE"),
    "billing page must classify admin credits via ADMIN_CREDIT_WHERE, not a single description match",
  );
});

