import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { stripCommentsAndStrings } from "./_source-tools.ts";
import { serverMonthlyCents, fleetMrrCents, type MrrServer } from "../lib/admin-metrics.ts";
import type { RenewalPrices } from "../lib/renewal-charge.ts";
import { isGrantLive } from "../lib/server-ownership-tags.ts";
import { nameTone, nameToneClass } from "../lib/creator-name.ts";

const NO_ADDONS: RenewalPrices = { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: 0 };
const vps = (over: Partial<MrrServer> = {}): MrrServer => ({
  status: "RUNNING", isFree: false, termMonths: 1, extraDiskGB: 0, dedicatedIp: null, wantsDedicatedIp: false,
  backupTier: "FREE", annualDiscountPct: null, plan: { name: "Starter", priceCents: 2160 }, gamePlan: null, ...over,
});

test("a live creator grant contributes $0 MRR even though isFree is false", () => {
  assert.equal(serverMonthlyCents(vps(), NO_ADDONS), 2160);
  assert.equal(serverMonthlyCents(vps({ grantLive: true }), NO_ADDONS), 0);
});

test("fleet MRR skips grant servers but keeps paid ones", () => {
  assert.equal(fleetMrrCents([vps({ grantLive: true }), vps(), vps({ isFree: true })], NO_ADDONS), 2160);
});

test("a grant that converted to paid counts again (grantLive false)", () => {
  const now = new Date("2026-10-02T00:00:00Z");
  const grant = { status: "ACTIVE", expiresAt: new Date("2026-10-20T00:00:00Z"), noticeSentAt: null, finalNoticeSentAt: null };
  const live = isGrantLive(grant, new Date("2026-10-20T00:00:00Z"), now);
  assert.equal(live, true);
  // Server expiry moved past the grant expiry => somebody paid => converted.
  const converted = isGrantLive(grant, new Date("2026-11-20T00:00:00Z"), now);
  assert.equal(converted, false);
  assert.equal(serverMonthlyCents(vps({ grantLive: converted }), NO_ADDONS), 2160);
  // REVOKED grant is not live either.
  assert.equal(isGrantLive({ ...grant, status: "REVOKED" }, null, now), false);
});

test("creator tone wins over the green paying tone; others keep theirs", () => {
  assert.equal(nameTone({ creator: true, paying: true }), "creator");
  assert.equal(nameTone({ creator: false, paying: true }), "paying");
  assert.equal(nameTone({ creator: false }), "default");
  assert.equal(nameToneClass("creator"), "nx-creator-name");
  assert.equal(nameToneClass("paying"), "text-emerald-300");
  assert.equal(nameToneClass("default"), "");
});

function walk(dir: string, out: string[] = []): string[] {
  for (const f of readdirSync(dir)) {
    if (f === "node_modules" || f === ".next" || f.startsWith(".")) continue;
    const p = join(dir, f);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(f)) out.push(p);
  }
  return out;
}

test("every file that prices MRR from servers also flags live creator grants", () => {
  const root = join(import.meta.dirname, "..");
  const offenders: string[] = [];
  for (const dir of ["app", "lib", "worker"]) {
    for (const file of walk(join(root, dir))) {
      if (file.endsWith("lib/admin-metrics.ts")) continue;
      const src = stripCommentsAndStrings(readFileSync(file, "utf8"));
      if (/\b(serverMonthlyCents|fleetMrrCents)\s*\(/.test(src) && !src.includes("withGrantLive")) offenders.push(file.slice(root.length + 1));
    }
  }
  assert.deepEqual(offenders, [], "these call serverMonthlyCents/fleetMrrCents without withGrantLive: creator grants would count as MRR");
});
